-- Ultimate audit (balance pass 2026-09i): new Balance Config field shared.ult.bossHit. Against Kings, Guardians, the Rival
-- and Umbra an Ultimate strike deals at least bossHit × its cap (ult.bossCap / ult.umbraCap) × max HP, so the caps
-- (and later forge cap levels) actually bind. Default 0 = today's game (only the monster-HP damage) until the pass is
-- published. Patches only the shared.ult subtree of the live config_schema, carrying every existing key.
update public.config_schema set schema = jsonb_set(schema,
  '{properties,shared,properties,ult}',
  $j${"description":"Ultimate (Judgement)","default":{},"type":"object","properties":{"max":{"default":80,"description":"Charge needed","type":"number","minimum":0,"maximum":800},"fill":{"default":60,"description":"Seconds to fill from time alone","type":"number","minimum":0,"maximum":600},"killCap":{"default":1,"description":"Kills can add at most this × the time rate (1 = at most twice as fast)","type":"number","minimum":0,"maximum":10},"perKill":{"default":1,"description":"Charge per kill","type":"number","minimum":0,"maximum":10},"perElite":{"default":5,"description":"Charge per elite kill","type":"number","minimum":0,"maximum":50},"perBoss":{"default":20,"description":"Charge per boss kill","type":"number","minimum":0,"maximum":200},"mobHp":{"default":1.5,"description":"Damage = this × the Chapter's normal monster HP (no Might/Power/crit)","type":"number","minimum":0,"maximum":10},"bossCap":{"default":0.08,"description":"At most this × a King's or Guardian's max HP per Ultimate","type":"number","minimum":0,"maximum":1},"umbraCap":{"default":0.05,"description":"At most this × Umbra's max HP per Ultimate","type":"number","minimum":0,"maximum":1},"bossHit":{"default":0,"description":"Against Kings, Guardians, the Rival and Umbra an Ultimate deals at least this share of its cap above (1 = always the cap, 0 = only the monster-HP damage)","type":"number","minimum":0,"maximum":1},"slow":{"default":0.55,"description":"Slow-motion time (s)","type":"number","minimum":0,"maximum":600},"delay":{"default":0.3,"description":"Strike delay (s)","type":"number","minimum":0,"maximum":600},"kb":{"default":120,"description":"Knockback","type":"number","minimum":0,"maximum":1200}}}$j$::jsonb)
where id = 1;
